<?php
require_once __DIR__.'/_bootstrap.php';
function xmlText(SimpleXMLElement $xml, string $xpath): string { $r=$xml->xpath($xpath); return $r&&isset($r[0])?trim((string)$r[0]):''; }
$q=$conn->query("SELECT dp.*,d.arquivo,d.mime_type,d.tipo,d.empresa_id FROM documento_processamentos dp JOIN documentos d ON d.id=dp.documento_id WHERE dp.status IN ('PENDENTE','ERRO') AND dp.tentativa<5 ORDER BY dp.id ASC LIMIT 20");
while($row=$q->fetch_assoc()){$id=(int)$row['id'];$doc=(int)$row['documento_id'];$conn->query("UPDATE documento_processamentos SET status='PROCESSANDO',tentativa=tentativa+1 WHERE id=$id");$conn->query("UPDATE documentos SET status_processamento='PROCESSANDO' WHERE id=$doc");try{$path=realpath(__DIR__.'/../'.$row['arquivo']);if(!$path||!is_file($path))throw new RuntimeException('Arquivo não encontrado.');$result=[];
if($row['tipo_processamento']==='EXTRACAO_LOCAL'){$raw=file_get_contents($path);libxml_use_internal_errors(true);$xml=simplexml_load_string($raw);if(!$xml)throw new RuntimeException('XML inválido.');$xml->registerXPathNamespace('nfe','http://www.portalfiscal.inf.br/nfe');$result=['chave'=>xmlText($xml,'//nfe:infNFe/@Id'),'numero'=>xmlText($xml,'//nfe:ide/nfe:nNF'),'serie'=>xmlText($xml,'//nfe:ide/nfe:serie'),'emitente'=>xmlText($xml,'//nfe:emit/nfe:xNome'),'cnpj_emitente'=>xmlText($xml,'//nfe:emit/nfe:CNPJ'),'destinatario'=>xmlText($xml,'//nfe:dest/nfe:xNome'),'valor_total'=>xmlText($xml,'//nfe:ICMSTot/nfe:vNF')];}
else{$endpoint=getenv('BCMR_AI_DOCUMENT_ENDPOINT')?:'';$key=getenv('BCMR_AI_DOCUMENT_KEY')?:'';if($endpoint===''||$key==='')throw new RuntimeException('IA externa não configurada. Defina BCMR_AI_DOCUMENT_ENDPOINT e BCMR_AI_DOCUMENT_KEY.');$payload=json_encode(['documento_id'=>$doc,'nome'=>basename($path),'mime_type'=>$row['mime_type'],'conteudo_base64'=>base64_encode(file_get_contents($path))]);$ch=curl_init($endpoint);curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_RETURNTRANSFER=>true,CURLOPT_HTTPHEADER=>['Content-Type: application/json','Authorization: Bearer '.$key],CURLOPT_POSTFIELDS=>$payload,CURLOPT_TIMEOUT=>45]);$resp=curl_exec($ch);$code=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);if($resp===false||$code<200||$code>=300)throw new RuntimeException('Falha no provedor de IA. HTTP '.$code);$result=json_decode($resp,true);if(!is_array($result))throw new RuntimeException('Resposta de IA inválida.');}
$json=json_encode($result,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);$s=$conn->prepare("UPDATE documento_processamentos SET status='CONCLUIDO',resultado_json=?,erro=NULL,processado_em=NOW() WHERE id=?");$s->bind_param('si',$json,$id);$s->execute();$s=$conn->prepare("UPDATE documentos SET status_processamento='CONCLUIDO',extraido_json=? WHERE id=?");$s->bind_param('si',$json,$doc);$s->execute();echo "Documento $doc concluído\n";}catch(Throwable $e){$err=substr($e->getMessage(),0,2000);$s=$conn->prepare("UPDATE documento_processamentos SET status='ERRO',erro=? WHERE id=?");$s->bind_param('si',$err,$id);$s->execute();$conn->query("UPDATE documentos SET status_processamento='ERRO' WHERE id=$doc");echo "Documento $doc erro: $err\n";}}
